mapper.update:
UPDATE inspection_exception
SET status = 'RETURNED',
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'
  AND version = #{expectedVersion}

UPDATE inspection_exception
SET status = 'PENDING',
    site_description = #{siteDescription},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'RETURNED'
  AND version = #{expectedVersion}

UPDATE inspection_exception
SET handler = #{handler},
    handle_result = #{handleResult},
    handled_at = #{now},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'CONFIRMED'
  AND version = #{expectedVersion}

UPDATE inspection_exception
SET status = 'CLOSED',
    closer = #{closer},
    closed_at = #{now},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'CONFIRMED'
  AND version = #{expectedVersion}
